CREATE TABLE geo_query_tasks(id text PRIMARY KEY,site_id text NOT NULL REFERENCES sites(id),actor_id text NOT NULL REFERENCES users(id),request_key text NOT NULL,brand text NOT NULL,question text NOT NULL,platform integer NOT NULL CHECK(platform BETWEEN 1 AND 8),mode text NOT NULL CHECK(mode IN ('demo','live')),status text NOT NULL CHECK(status IN ('queued','processing','hit','miss','failed','review')),provider_id text,share_url text,screenshot_url text,matched_word text,error text,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(site_id,request_key,platform));
CREATE INDEX geo_query_site_created ON geo_query_tasks(site_id,created_at DESC);
